import os,json,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    ones=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    out=[row[:] for row in g]
    rows=[r for r in range(h) if sum(1 for r_,c_ in ones if r_==r)>=2]
    cols=[c for c in range(w) if sum(1 for r_,c_ in ones if c_==c)>=2]
    for r in rows:
        for c in range(w): out[r][c]=1
    for c in cols:
        for r in range(h): out[r][c]=1
    # find 2-blocks
    seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]==2 and not seen[r][c]:
                stack=[(r,c)]; comp=[]
                seen[r][c]=True
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==2 and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                hit = any(r0-1<=R<=r1+1 for R in rows) or any(c0-1<=C<=c1+1 for C in cols)
                if hit:
                    for y,x in comp: out[y][x]=1
    return out

